{
  "reviews": [
    {
      "label": "A",
      "verdict": "needs_revision",
      "findings": [
        {
          "location": "“评审须读实际定稿与来源……覆盖需求……与过程语言”",
          "problem": "评审输入未明确包含原始需求，所列评审覆盖遗漏自然表达。",
          "source_evidence": "S2要求评审阅读实际完整成稿、需求和相关来源，并明确要求覆盖自然表达。",
          "required_change": "明确将需求交给评审，并补充自然表达检查。"
        },
        {
          "location": "“须更正的问题解决后方可交付，最后跑check_delivery验收”",
          "problem": "实际验收流程不完整：未要求当前整篇报告通过评估，也未说明交付记录绑定及最终状态；运行检查器还缺少脚本执行可用的条件。",
          "source_evidence": "S2要求当前报告通过整篇评估，以state/final_delivery.json绑定交付材料、必要输入、评审和交付消息，最终状态为final/complete；脚本执行可用时运行检查器。",
          "required_change": "补齐这些验收条件，并将检查器执行表述为有条件的步骤。"
        }
      ],
      "basis": "正确选择full与independent，正确解释同用Astra及无需外部人员，保留S1、S2且未声称已执行工具。所给整篇281字符符合长度限制，但评审覆盖和实际验收步骤仍有实质遗漏。"
    },
    {
      "label": "B",
      "verdict": "needs_revision",
      "findings": [
        {
          "location": "整篇",
          "problem": "所给整篇长度为945个非空白Unicode字符，超过320字符上限。",
          "source_evidence": "简报要求操作建议整篇含标题和引文共220—320个非空白Unicode字符；所给测量met为false。",
          "required_change": "压缩至规定范围，同时保留必要操作建议和来源编号。"
        },
        {
          "location": "上下文安排：“只交换……不共享推理过程”",
          "problem": "将上下文分离扩展为来源未规定的信息交换禁令。",
          "source_evidence": "S2要求非作者上下文及阅读完整成稿、需求和相关来源，未规定只能交换哪些信息或禁止共享推理过程。",
          "required_change": "删除该额外限制，或明确其只是建议而非来源规定。"
        },
        {
          "location": "参考文献",
          "problem": "为S1、S2添加了所给材料未确认的文件出处。",
          "source_evidence": "所给来源提供编号和正文标题，没有确认S1来自SKILL.md或S2来自references/subagents-and-review-loop.md。",
          "required_change": "保留S1、S2及已提供的标题，删除未经支持的文件路径归属。"
        }
      ],
      "basis": "档位、独立上下文、同厂商可用、不得以self替代、主要评审维度及大部分验收流程均有来源支持，也未虚构执行完成。但长度明显不合规，并加入了无来源支持的限制和出处。"
    },
    {
      "label": "C",
      "verdict": "needs_revision",
      "findings": [
        {
          "location": "整篇",
          "problem": "所给整篇长度为365个非空白Unicode字符，超过320字符上限。",
          "source_evidence": "要求整篇220—320字符；所给测量met为false。",
          "required_change": "压缩至规定范围。"
        },
        {
          "location": "“按S2八项视角……领域specialist……逐项检查”",
          "problem": "将领域专家检查列为本任务必需项目。",
          "source_evidence": "S2明确只有任务需要专业方法时才选择领域专家，不应给每份报告附加所有专家。",
          "required_change": "保留通用评审维度；领域专家仅在确有需要时安排。"
        },
        {
          "location": "上下文安排与验收中的“绑定……版本哈希”",
          "problem": "未明确评审同时读取需求与两份来源，且将版本绑定具体化为来源未要求的哈希。",
          "source_evidence": "S2要求评审阅读完整成稿、需求及相关来源；交付记录需绑定当前材料、必要输入、评审和交付消息，并未规定使用版本哈希。",
          "required_change": "明确评审输入，并用来源支持的版本及交付记录绑定要求替代强制哈希表述。"
        }
      ],
      "basis": "正确选择full与independent，也正确说明新Astra上下文可以评审，无需外部人员或另一家模型；修复及有证据的不采纳处置基本忠实。长度、专家适用条件和输入及绑定说明仍需修订。"
    },
    {
      "label": "D",
      "verdict": "needs_revision",
      "findings": [
        {
          "location": "“规划阶段……输入与版本绑定；评审需覆盖……”",
          "problem": "没有说明评审必须直接阅读完整成稿、原始需求与相关来源，而非作者摘要；覆盖清单也未明确过程语言清理。",
          "source_evidence": "S2明确规定评审的实际阅读输入，并将过程语言检查列为通用评审覆盖内容。",
          "required_change": "明确交给独立上下文的实际材料，并纳入过程语言检查。"
        },
        {
          "location": "结尾的交付条件",
          "problem": "仅说明评审通过及修改解决，没有给出用户要求的实际验收操作。",
          "source_evidence": "S2要求当前整篇评估通过、清理内部过程信息、建立交付绑定记录、达到final/complete状态，并在脚本执行可用时运行交付检查器。",
          "required_change": "补充可执行的验收步骤，包括当前整篇评估、交付记录及状态核对和有条件的检查器执行。"
        }
      ],
      "basis": "所给整篇241字符符合限制，档位选择、独立性的含义、Astra上下文安排及负评阻止交付的说明正确，保留来源且未虚构执行。但评审输入和实际验收操作覆盖不足。"
    }
  ]
}
